update public.sarpras_katalog set spesifikasi='{"nama_form": "WiFi Router/Modem", "default": "Tipe: Wifi Router or Modem DTW6142\n[Working condition]\nWorking temp: 0~+50°C\nWorking humidity: 5~90% (non-condensing)\n[Storing condition]\nStoring temp: -30~+60°C\nStoring humidity: 5~90% (non-condensing)\nPower adapter: DC 12V, 1A\nPower supply: ≤12W\n[User Interface]\nEthernet: 4*10/100/1000Mbps auto-adaptive Ethernet interface RJ45 connectors (1WAN, 3*LAN)\n[WLAN Interface]\nStandard: Compliant with IEEE802.11b/g/n/ac/ax\nSpeed: 2402 Mbps (5GHz); 574 Mbps (2.4GHz)\nAntennas: 2.4GHz: 2*2, 5GHz: 2*2 (external antennas)\nMax connected devices: 128\n[Management & Network Features]\nManagement: WEB/Telnet/TR-069/SSH/CLI", "variants": {}}'::jsonb,gambar='{"files": ["./assets/img/sarpras/ops_kasir_router.jpg", "./assets/img/sarpras/ops_kasir_router_referensi.jpg"]}'::jsonb,daftar_tipe='[]'::jsonb where item_id='OPS_KASIR_ROUTER';
update public.sarpras_katalog set spesifikasi='{"nama_form": "UPS", "default": "Tipe: UPS Dianfengbao 1000VA\nRated Load Capacity: 1000VA/600W\nInput Voltage: 140-265Vac (Battery inverter outputs when exceeded)\nOutput Voltage: 220V±10% (Battery model)\nTransfer Time: 4-8ms\nOutput Waveform: Simulated Sine Wave\nNoise: ≤40dB\nBattery Model: 12V9AH\nNumber of Batteries: 1 piece\nCharging Time: 90% capacity in 6 hours\nOperating Environment: 0~90% humidity, 0-40°C temperature\nWeight: 6KG", "variants": {}}'::jsonb,gambar='{"files": ["./assets/img/sarpras/ops_kasir_ups.jpg", "./assets/img/sarpras/ops_kasir_ups_referensi.jpg"]}'::jsonb,daftar_tipe='[]'::jsonb where item_id='OPS_KASIR_UPS';
update public.sarpras_katalog set spesifikasi='{"nama_form": "IP Camera Indoor", "default": "Resolusi Maksimum: 1920 x 1080 (Full HD) at 30 fps\nImage Sensor: 1/2.8\" Progressive Scan CMOS\nMode Siang/Malam: IR Cut Filter with up to 30m (or 40m depending on specific regional revision)\nLensa: 2.8 mm lens, 4 mm lens, 6 mm lens\nSudut Pandang Horizontal (FOV): 112° (2.8 mm), 89° (4 mm), 54° (6 mm)\nKompresi Video: H.265+, H.265, H.264+, H.264, dan MJPEG\nVideo Streaming: Mendukung hingga 3 stream video secara bersamaan\nTingkat Perlindungan: IP67\nKetahanan Benturan: IK10\nPower Supply: DC 12V + 25% and Power over Ethernet (PoE)", "variants": {}}'::jsonb,gambar='{"files": ["./assets/img/sarpras/kmn_cctv_ipcam_indoor.jpg"]}'::jsonb,daftar_tipe='[]'::jsonb where item_id='KMN_CCTV_IPCAM_INDOOR';
update public.sarpras_katalog set spesifikasi='{"nama_form": "IP Camera Outdoor", "default": "Resolusi Maksimum: 1920 x 1080 (Full HD) at 25/30 fps\nImage Sensor: 1/2.8\" Progressive Scan CMOS\nMode Siang/Malam: IR Cut Filter with up to 30m (or 40m depending on specific regional revision)\nLensa: 2.8 mm lens, 4 mm lens, 6 mm lens\nSudut Pandang Horizontal (FOV): 112° (2.8 mm), 89° (4 mm), 54° (6 mm)\nKompresi Video: H.265+, H.265, H.264+, H.264, dan MJPEG\nVideo Streaming: Mendukung hingga 3 stream video secara bersamaan\nFitur Gambar: BLC, HLC, 3D DNR, Digital WDR atau True WDR, ROI\nTingkat Perlindungan: IP67\nKetahanan Benturan: IK10\nPower Supply: DC 12V + 25% and Power over Ethernet (PoE)", "variants": {}}'::jsonb,gambar='{"files": ["./assets/img/sarpras/kmn_cctv_ipcam_outdoor.jpg"]}'::jsonb,daftar_tipe='[]'::jsonb where item_id='KMN_CCTV_IPCAM_OUTDOOR';
update public.sarpras_katalog set spesifikasi='{"nama_form": "NVR 8 Channel", "default": "Jumlah Channel: Minimal 8 Channel IP Camera\nResolusi Perekaman: Mendukung hingga 8 MP\nKompresi Video: H.265+, H.265, H.264+, H.264\nBandwidth Incoming: Minimal 80 Mbps\nVideo Output: HDMI dan VGA\nPenyimpanan: Minimal 1 SATA, mendukung HDD hingga 10 TB\nAntarmuka Jaringan: 1 X RJ45 Gigabit Ethernet (10/100/1000 Mbps)\nStandar Jaringan: Mendukung ONVIF serta protokol TCP/IP, DHCP, DNS, RTSP, HTTP/HTTPS\nUSB Port: Minimal 2 X USB\nRemote Access: Mendukung monitoring melalui PC Client dan aplikasi Android/iOS\nPower Supply: DC 12V", "variants": {}}'::jsonb,gambar='{"files": ["./assets/img/sarpras/kmn_cctv_nvr.jpg"]}'::jsonb,daftar_tipe='[]'::jsonb where item_id='KMN_CCTV_NVR';
update public.sarpras_katalog set spesifikasi='{"nama_form": "POE Switch 10 Port", "default": "Jumlah Port: Minimal 8 Port PoE + 2 Port Uplink\nStandar PoE: IEEE 802.3af/at\nPoE Output: Maksimal 30 W per port\nTotal PoE Budget: Minimal 96 W\nSwitching Capacity: Minimal 5.6 Gbps\nAntarmuka: RJ45 Ethernet\nFitur: Auto Negotiation, Auto MDI/MDIX, Store-and-Forward\nPower Supply: AC 100–240V\nMaterial: Metal Housing", "variants": {}}'::jsonb,gambar='{"files": ["./assets/img/sarpras/kmn_cctv_poe_switch.jpg"]}'::jsonb,daftar_tipe='[]'::jsonb where item_id='KMN_CCTV_POE_SWITCH';
update public.sarpras_katalog set spesifikasi='{"nama_form": "HDD Minimal 2 TB", "default": "Kapasitas: Minimal 2 TB\nForm Factor: 3.5 Inch\nInterface: SATA III 6 Gb/s atau lebih tinggi\nKecepatan Putaran: 5.400 RPM atau lebih tinggi\nCache Buffer: Minimal 64 MB\nOperasional: Mendukung operasi 24/7 untuk sistem CCTV", "variants": {}}'::jsonb,gambar='{"files": ["./assets/img/sarpras/kmn_cctv_hdd.jpg"]}'::jsonb,daftar_tipe='[]'::jsonb where item_id='KMN_CCTV_HDD';
update public.sarpras_katalog set spesifikasi='{"nama_form": "Kabel LAN Cat 6", "default": "Jenis Kabel: Kabel UTP CAT 6\nKonduktor: Solid Copper\nUkuran: 23 AWG\nJumlah Core: 4 Pair (8 Core)\nBandwidth: 250 MHz\nKecepatan Data: Gigabit Ethernet 10/100/1000 Mbps\nPanjang: 305 Meter/Box\nImpedansi: 100 Ohm\nJacket: PVC atau LSZH\nAplikasi: LAN, CCTV IP Camera, dan PoE", "variants": {}}'::jsonb,gambar='{"files": ["./assets/img/sarpras/kmn_cctv_kabel_lan.jpg"]}'::jsonb,daftar_tipe='[]'::jsonb where item_id='KMN_CCTV_KABEL_LAN';
update public.sarpras_katalog set spesifikasi='{"nama_form": "LED Display 19 Inch", "default": "Ukuran Layar: 19 inci atau 24 inci\nResolusi: Minimal Full HD (1920 x 1080) (untuk 19\" dapat menerima HD+ 1600 x 900 apabila Full HD tidak tersedia)\nPanel: IPS atau VA atau TN\nAspect Ratio: 16:9\nRefresh Rate: Minimal 60 Hz\nBrightness: Minimal 250 cd/m²\nVideo Input: Minimal HDMI dan VGA\nPower Supply: AC 100–240V", "variants": {}}'::jsonb,gambar='{"files": ["./assets/img/sarpras/kmn_cctv_led_display.jpg"]}'::jsonb,daftar_tipe='[]'::jsonb where item_id='KMN_CCTV_LED_DISPLAY';
update public.sarpras_katalog set spesifikasi='{"nama_form": "Wallmount Rack Server 4U", "default": "Jenis: Wallmount Rack Cabinet 4U\nUkuran: 4U (19 Inch Standard Rack)\nTinggi Rack: Wall Mount (dinding)\nMaterial: Steel/SPCC dengan ketebalan minimal 1,0 mm\nPintu Depan: Tempered Glass dengan kunci\nPanel Samping: Removable Panel\nMounting Rail: Adjustable 19 Inch Rack Mount", "variants": {}}'::jsonb,gambar='{"files": ["./assets/img/sarpras/kmn_cctv_rack.jpg"]}'::jsonb,daftar_tipe='[]'::jsonb where item_id='KMN_CCTV_RACK';